package fraymus.workspace;
import org.json.*;
import java.util.*;
import java.util.regex.*;
/** Parse declared semantic options only; engine stores retain range/source/physics validation. */
final class Requested044 {
 static String match(String s,String re){var m=Pattern.compile(re,Pattern.CASE_INSENSITIVE).matcher(s);return m.find()?m.group(1):null;}
 static void number(JSONObject o,String k,String s,String re){re=re.replace("\\d+(?:\\.\\d+)?","(?:\\d+(?:\\.\\d+)?|\\.\\d+)");String m=match(s,re);if(m!=null)o.put(k,Double.parseDouble(m));}
 static JSONObject fields(String s,String family){if(family.equals("rehearsal"))return Rehearsal073.request(s);var out=new JSONObject();String name=match(s,"\\b(?:procedure|skill|workflow)\\s+(?:as|named)\\s+([a-z][a-z0-9-]{2,55})\\b");if(name!=null)out.put("saveSkillName",name);
  switch(family){
   case "construction"->{for(String k:List.of("centerX","centerZ","forceLimitN","torqueLimitNm","requiredLoadN"))number(out,k,s,"\\b"+k+"\\s*(?:=|:)?\\s*([+\\-]?\\d+(?:\\.\\d+)?)");}
   case "map"->{number(out,"seed",s,"\\bseed\\s*(?:=|:)?\\s*(\\d+)");number(out,"width",s,"\\bwidth\\s*(?:of|=|:)?\\s*(\\d+)");number(out,"height",s,"\\bheight\\s*(?:of|=|:)?\\s*(\\d+)");number(out,"disturbanceNs",s,"\\bimpulse\\s*(?:of|=|:)?\\s*([+-]?\\d+(?:\\.\\d+)?)");var c=new JSONObject();if(ChatPolicy044.has(s,"\\b(fully connected|global topology|all floor cells connected)\\b"))c.put("connected",true);for(String k:List.of("minFloorFraction","maxFloorFraction","minRouteSteps","maxRouteSteps")){String prefix=switch(k){case"minFloorFraction"->"minimum floor fraction";case"maxFloorFraction"->"maximum floor fraction";case"minRouteSteps"->"minimum route steps";default->"maximum route steps";};number(c,k,s,prefix+"\\s+([.\\d]+)");}if(!c.isEmpty())out.put("constraints",c);String m=match(s,"materials\\s+JSON\\s*:\\s*(\\[[^\\n]*?\\])");if(m!=null)out.put("materials",new JSONArray(m));}
   case "space"->{for(var e:Map.of("dimensions","\\b(\\d{1,2})\\s*[- ]?d\\b","seed","\\bseed\\s*(?:of|=|:)?\\s*(\\d+)","samples","\\b(\\d+)\\s+(?:attractors|samples)\\b","rooms","\\b(\\d+)\\s+rooms\\b","iterations","\\b(\\d+)\\s+(?:iterations|growth steps)\\b","side","\\bside\\s*(?:length|=|:)?\\s*(\\d+)").entrySet())number(out,e.getKey(),s,e.getValue());if(ChatPolicy044.has(s,"\\bdungeon\\b"))out.put("type","dungeon");else if(ChatPolicy044.has(s,"\\bcoloni[sz]ation\\b"))out.put("type","colonization");}
   case "data"->{number(out,"maxGapS",s,"\\bgap(?:\\s+(?:threshold|limit))?\\s*(?:of|=|:)?\\s*([+\\-]?\\d+(?:\\.\\d+)?)");number(out,"speedLimitMps",s,"\\bspeed(?:\\s+(?:threshold|limit))?\\s*(?:of|=|:)?\\s*([+\\-]?\\d+(?:\\.\\d+)?)");}
   case "push","spatial"->{String literal=match(s,"\\bdisplacement(?:M)?\\s*(?:of|=|:)?\\s*(\\[\\s*[+\\-]?\\d+(?:\\.\\d+)?\\s*,\\s*[+\\-]?\\d+(?:\\.\\d+)?\\s*,\\s*[+\\-]?\\d+(?:\\.\\d+)?\\s*\\])");if(literal!=null)out.put("displacementM",new JSONArray(literal));if(family.equals("push")){String x=match(s,"\\bX\\s*(?:by|=|:)?\\s*([+-]?\\d+(?:\\.\\d+)?)"),z=match(s,"\\bZ\\s*(?:by|=|:)?\\s*([+-]?\\d+(?:\\.\\d+)?)");if(x!=null||z!=null)out.put("displacementM",new JSONArray(new double[]{x==null?0:Double.parseDouble(x),0,z==null?0:Double.parseDouble(z)}));number(out,"initialForceN",s,"(?:initial|gentle)(?: push(?:ing)?)? force\\s*(?:limit|of|=|:)?\\s*([.\\d]+)");number(out,"maxForceN",s,"(?:maximum|max) force\\s*(?:limit|of|=|:)?\\s*([.\\d]+)");if(ChatPolicy044.has(s,"\\b(active|validated|approved)\\b.{0,40}\\bcontact controller\\b"))out.put("useContactController",true);if(ChatPolicy044.has(s,"\\b(active|learned|validated)\\b.{0,40}\\b(force |pushing )?profile\\b"))out.put("useActiveProfile",true);}}
   case "perception"->{number(out,"seconds",s,"\\bfor\\s+(\\d+(?:\\.\\d+)?)\\s+seconds?\\b");}
   default->{number(out,"angleDeg",s,"\\b([+\\-]?\\d+(?:\\.\\d+)?)\\s*(?:degrees?|°)");number(out,"friction",s,"\\bfriction\\s*(?:of|=|:)?\\s*([+\\-]?\\d+(?:\\.\\d+)?)");number(out,"targetM",s,"\\btarget\\s*(?:of|=|:)?\\s*([+\\-]?\\d+(?:\\.\\d+)?)");number(out,"disturbanceMps",s,"([+\\-]?\\d+(?:\\.\\d+)?)\\s*m/s\\s+disturbance");if(ChatPolicy044.has(s,"\\b(include|attach)\\b[^.!?\\n]{0,120}\\bbrowser\\b"))out.put("browserContext",true);}
  }return out;
 }
 static JSONObject preserve(JSONObject args,JSONObject required){var out=WorldFrames.copy(args);for(String k:required.keySet()){if(required.get(k) instanceof JSONObject nested){if(out.has(k)&&!(out.get(k) instanceof JSONObject))throw new IllegalArgumentException("Preserve explicitly requested object "+k);out.put(k,preserve(out.optJSONObject(k,new JSONObject()),nested));continue;}if(out.has(k)&&!new JSONObject().put("v",out.get(k)).similar(new JSONObject().put("v",required.get(k))))throw new IllegalArgumentException("Preserve explicitly requested "+k+"="+required.get(k));out.put(k,required.get(k));}return out;}
}
